"""Qualify the bounded passive TCP listener and echo state."""
import argparse,hashlib,importlib,json,os,subprocess,sys
from pathlib import Path
from layout_text import LayoutText
HERE=Path(__file__).resolve().parent.parent
def run(cmd,*,cwd=HERE,env=None):
 r=subprocess.run(list(map(str,cmd)),cwd=cwd,capture_output=True,env=env);assert r.returncode==0,(cmd,r.returncode,r.stdout[-2000:],r.stderr[-8000:]);return r.stdout
HOST=r'''
#include "network_tcp_listener.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(x) check((x),__LINE__)
static void check(bool ok,int line){if(!ok){fprintf(stderr,"listener check failed at %d\n",line);exit(1);}}
static const NetworkEngineMac LOCAL={{0x52,0x54,0,0x12,0x34,0x56}},PEER={{2,0,0,0,0,1}};
static NetworkEnginePayload payload(size_t n,uint8_t salt){NetworkEnginePayload p={0};p.len=n;for(size_t i=0;i<n;i++)p.bytes[i]=(uint8_t)(i*17+salt);return p;}
static NetworkEngineFrame peer(NetworkTcpListener *l,uint32_t seq,uint32_t ack,uint8_t flags,const NetworkEnginePayload *p){NetworkEngineFrame f={0};CHECK(network_engine_tcp_build(&f,l->local_mac,l->peer_mac,l->peer_ip,l->config.local,l->peer_port,l->config.listen_port,seq,ack,flags,4096,p));return f;}
static NetworkTcpPacket output(NetworkTcpListenerOutput o){CHECK(o.present);NetworkTcpPacket p=network_engine_tcp_decode(&o.frame);CHECK(p.valid);return p;}
static void handshake(NetworkTcpListener *l,uint32_t client_seq,uint64_t now){NetConfig c=net_config_controlled();CHECK(network_tcp_listener_init(l,c,LOCAL,UINT64_C(0x7365786f735f3736),now));NetworkEnginePayload empty={0};NetworkEngineFrame syn={0};CHECK(network_engine_tcp_build(&syn,LOCAL,PEER,c.http,c.local,62000,c.listen_port,client_seq,0,NETWORK_TCP_SYN,4096,&empty));CHECK(network_tcp_listener_ingest(l,&syn,now));NetworkTcpPacket synack=output(network_tcp_listener_advance(l,now));CHECK((synack.flags&(NETWORK_TCP_SYN|NETWORK_TCP_ACK))==(NETWORK_TCP_SYN|NETWORK_TCP_ACK)&&synack.acknowledgment==client_seq+1);NetworkEngineFrame ack=peer(l,client_seq+1,synack.sequence+1,NETWORK_TCP_ACK,&empty);CHECK(network_tcp_listener_ingest(l,&ack,now+1)&&l->state==NETWORK_LISTENER_ESTABLISHED);}
static void ack_pending(NetworkTcpListener *l,uint32_t seq,uint64_t now){NetworkEnginePayload empty={0};NetworkEngineFrame ack=peer(l,seq,l->pending_end,NETWORK_TCP_ACK,&empty);CHECK(network_tcp_listener_ingest(l,&ack,now));}
static void echo_many_and_stats(void){NetworkTcpListener l;handshake(&l,0xfffffff0,0);uint32_t client=l.rcv_nxt;uint64_t now=2,total=0;uint64_t expected_hash=UINT64_C(0xcbf29ce484222325);for(unsigned round=0;round<25;round++){size_t n=round==24?1:512;NetworkEnginePayload in=payload(n,(uint8_t)round);for(size_t i=0;i<n;i++)expected_hash=(expected_hash^in.bytes[i])*UINT64_C(0x100000001b3);NetworkEngineFrame data=peer(&l,client,l.snd_nxt,NETWORK_TCP_PSH|NETWORK_TCP_ACK,&in);CHECK(network_tcp_listener_ingest(&l,&data,now++));client+=n;CHECK(output(network_tcp_listener_advance(&l,now++)).flags==NETWORK_TCP_ACK);size_t echoed=0;while(echoed<n){NetworkTcpPacket e=output(network_tcp_listener_advance(&l,now++));CHECK(e.payload_length<=256);for(size_t i=0;i<e.payload_length;i++)CHECK(l.pending.bytes[e.payload_offset+i]==in.bytes[echoed+i]);echoed+=e.payload_length;ack_pending(&l,client,now++);}total+=n;}NetworkTcpListenerStats s=network_tcp_listener_statistics(&l);CHECK(total==12289&&s.received==total&&s.queued==total&&s.flow_received==total&&s.flow_queued==total&&s.receive_hash==expected_hash&&s.queue_hash==expected_hash&&s.flow_receive_hash==expected_hash&&s.flow_queue_hash==expected_hash);}
static void retransmit_duplicate_gap_and_rst(void){NetworkTcpListener l;handshake(&l,100,10);uint32_t seq=l.rcv_nxt;NetworkEnginePayload in=payload(100,4);NetworkEngineFrame data=peer(&l,seq,l.snd_nxt,NETWORK_TCP_PSH|NETWORK_TCP_ACK,&in);CHECK(network_tcp_listener_ingest(&l,&data,12));(void)network_tcp_listener_advance(&l,12);NetworkTcpListenerOutput first=network_tcp_listener_advance(&l,12);CHECK(first.present);CHECK(!network_tcp_listener_advance(&l,1011).present);NetworkTcpListenerOutput replay=network_tcp_listener_advance(&l,1012);CHECK(replay.present&&first.frame.length==replay.frame.length&&!memcmp(first.frame.bytes,replay.frame.bytes,first.frame.length));NetworkTcpListenerStats before=l.stats;CHECK(network_tcp_listener_ingest(&l,&data,1013));CHECK(l.stats.received==before.received&&l.receive_len==100);(void)network_tcp_listener_advance(&l,1013);NetworkEngineFrame gap=peer(&l,l.rcv_nxt+10,l.snd_una,NETWORK_TCP_ACK,&in);CHECK(network_tcp_listener_ingest(&l,&gap,1014));CHECK(l.receive_len==100);(void)network_tcp_listener_advance(&l,1014);NetworkEnginePayload empty={0};NetworkEngineFrame rst=peer(&l,l.rcv_nxt,l.snd_nxt,NETWORK_TCP_RST|NETWORK_TCP_ACK,&empty);CHECK(network_tcp_listener_ingest(&l,&rst,1015)&&l.state==NETWORK_LISTENER_LISTEN&&l.receive_len==0);handshake(&l,200,1020);CHECK(l.state==NETWORK_LISTENER_ESTABLISHED);}
static void fin_last_ack_and_failures(void){NetworkTcpListener l;handshake(&l,300,20);NetworkEnginePayload empty={0};NetworkEngineFrame fin=peer(&l,l.rcv_nxt,l.snd_nxt,NETWORK_TCP_FIN|NETWORK_TCP_ACK,&empty);CHECK(network_tcp_listener_ingest(&l,&fin,22));CHECK(output(network_tcp_listener_advance(&l,22)).flags==NETWORK_TCP_ACK);NetworkTcpPacket ours=output(network_tcp_listener_advance(&l,23));CHECK((ours.flags&NETWORK_TCP_FIN)!=0&&l.state==NETWORK_LISTENER_LAST_ACK);ack_pending(&l,l.rcv_nxt,24);CHECK(l.state==NETWORK_LISTENER_LISTEN);
 handshake(&l,400,30);NetworkEnginePayload big=payload(1460,2);for(unsigned i=0;i<2;i++){NetworkEngineFrame f=peer(&l,l.rcv_nxt,l.snd_nxt,NETWORK_TCP_PSH|NETWORK_TCP_ACK,&big);CHECK(network_tcp_listener_ingest(&l,&f,32+i));(void)network_tcp_listener_advance(&l,32+i);}NetworkEngineFrame overflow=peer(&l,l.rcv_nxt,l.snd_nxt,NETWORK_TCP_PSH|NETWORK_TCP_ACK,&big);CHECK(!network_tcp_listener_ingest(&l,&overflow,34)&&l.state==NETWORK_LISTENER_FAILED);
 handshake(&l,500,40);CHECK(!network_tcp_listener_advance(&l,39).present&&l.state==NETWORK_LISTENER_FAILED);}
static void listen_and_tuple_refusals(void){NetworkTcpListener l;NetConfig c=net_config_controlled();CHECK(network_tcp_listener_init(&l,c,LOCAL,1,0));NetworkEnginePayload empty={0};NetworkEngineFrame no_syn={0};CHECK(network_engine_tcp_build(&no_syn,LOCAL,PEER,c.http,c.local,62000,c.listen_port,1,0,0,4096,&empty));CHECK(!network_tcp_listener_ingest(&l,&no_syn,1)&&l.state==NETWORK_LISTENER_LISTEN);NetworkEngineFrame wrong_port={0};CHECK(network_engine_tcp_build(&wrong_port,LOCAL,PEER,c.http,c.local,62000,c.listen_port+1,1,0,NETWORK_TCP_SYN,4096,&empty));CHECK(!network_tcp_listener_ingest(&l,&wrong_port,2)&&l.state==NETWORK_LISTENER_LISTEN);handshake(&l,600,10);NetworkEngineFrame foreign={0};CHECK(network_engine_tcp_build(&foreign,l.local_mac,l.peer_mac,l.peer_ip+1,l.config.local,l.peer_port,l.config.listen_port,l.rcv_nxt,l.snd_nxt,NETWORK_TCP_ACK,4096,&empty));CHECK(!network_tcp_listener_ingest(&l,&foreign,12)&&l.state==NETWORK_LISTENER_ESTABLISHED);}
static void retry_exhaustion(void){NetworkTcpListener l;NetConfig c=net_config_controlled();CHECK(network_tcp_listener_init(&l,c,LOCAL,1,0));NetworkEnginePayload empty={0};NetworkEngineFrame syn={0};CHECK(network_engine_tcp_build(&syn,LOCAL,PEER,c.http,c.local,62000,c.listen_port,700,0,NETWORK_TCP_SYN,4096,&empty));CHECK(network_tcp_listener_ingest(&l,&syn,0));for(uint64_t now=0;now<=4000;now+=1000)CHECK(network_tcp_listener_advance(&l,now).present);CHECK(!network_tcp_listener_advance(&l,5000).present&&l.state==NETWORK_LISTENER_FAILED);}
int main(void){echo_many_and_stats();retransmit_duplicate_gap_and_rst();fin_last_ack_and_failures();listen_and_tuple_refusals();retry_exhaustion();puts("PASS listener handshake echo replay duplicate gap reset close stats and bounds");return 0;}
'''
def main():
 p=argparse.ArgumentParser();p.add_argument('--cesta',type=Path,required=True);p.add_argument('--cesta-source',type=Path);p.add_argument('--lean-root',type=Path);p.add_argument('--output',type=Path,default=HERE/'build/network-tcp-listener-tests');a=p.parse_args();w=a.output.resolve();w.mkdir(parents=True,exist_ok=True);inv=json.loads((HERE/'interfaces/network_tcp_listener.source.json').read_text())
 for path,key in ((inv['library_path'],'library_sha256'),(inv['tests_path'],'tests_sha256')):actual=run(['git','show',f"{inv['pin']}:{path}"],cwd=HERE.parent);assert hashlib.sha256(actual).hexdigest()==inv[key]
 cargo=run(['cargo','test','-p','sex-net','--lib','--','--test-threads=1'],cwd=HERE.parent);assert b'54 passed' in cargo;host=w/'host.c';host.write_text(HOST);names=('network_config','network_engine_frame','network_engine_packet','network_engine_tcp_packet','network_tcp_listener');exports={};plans={};configs=[]
 for cc in ('gcc','clang'):
  sources=[]
  for name in names:
   out=w/f'{name}-{cc}.c';cmd=[a.cesta,'export-c',f'src/{name}.cesta','--cc',cc,'--std=c11','-o',out]
   if name=='network_tcp_listener':plan=w/f'{name}-{cc}.plan';cmd.extend(['--plan',plan]);exports[cc]=out;plans[cc]=plan
   run(cmd+['--','-Igenerated/include']);sources.append(out)
  for mode,flags in (('O0',['-O0']),('O2',['-O2']),('SAN',['-O1','-fsanitize=address,undefined','-fno-sanitize-recover=all','-fno-pie','-no-pie'])):
   b=w/f'{cc}-{mode}';run([cc,'-std=c11','-Wall','-Wextra','-Wpedantic','-Werror',*flags,'-Igenerated/include',*sources,host,'-o',b]);actual=run([b],env={**os.environ,'ASAN_OPTIONS':'detect_leaks=1:abort_on_error=1'});configs.append({'compiler':cc,'mode':mode,'sha256':hashlib.sha256(actual).hexdigest()})
 base=LayoutText(exports['gcc'].read_text());mutations=[('syn-required','(tcp.flags&NETWORK_TCP_SYN)==0','false'),('listen-port','tcp.destination_port!=l->config.listen_port','false'),('tuple-source','ip.source==l->peer_ip','true'),('pending-ack','tcp.acknowledgment==l->pending_end','true'),('duplicate-suppression','tcp.sequence==l->rcv_nxt','true'),('retry-limit','l->retries>=NETWORK_TCP_LISTENER_RETRY_LIMIT','false'),('rst-rearm','tcp.flags&NETWORK_TCP_RST','false'),('fin-close','tcp.flags&NETWORK_TCP_FIN','false'),('shift-buffer','listener_shift(l,count)','(void)count'),('receive-capacity','tcp.payload_length>NETWORK_TCP_LISTENER_BUFFER-l->receive_len','false')];caught=[];prefix=[w/f'{n}-gcc.c' for n in names[:-1]]
 for name,old,new in mutations:
  assert base.count(old)>=1,(name,base.count(old));m=w/f'mutant-{name}.c';m.write_text(base.replace(old,new));b=w/f'mutant-{name}';run(['gcc','-std=c11','-O2','-Igenerated/include',*prefix,m,host,'-o',b]);r=subprocess.run([b],cwd=HERE,capture_output=True);assert r.returncode!=0,('survived',name,r.stdout,r.stderr);caught.append(name)
 admission=[]
 if a.lean_root:
  assert a.cesta_source;sys.path.insert(0,str(a.cesta_source.resolve()/'tests'));h=importlib.import_module('ownership_admission');unique={}
  for plan in plans.values():unique[hashlib.sha256(plan.read_bytes()).hexdigest()]=plan
  for i,plan in enumerate(unique.values()):(record,)=h.parse(plan.read_bytes());admission.append(h.admit_record(record,w/f'Listener{i}.lean',a.lean_root.resolve()))
 (w/'summary.json').write_text(json.dumps({'pin':inv['pin'],'upstream_rust_tests':54,'configurations':configs,'mutants_caught':caught,'admission':admission},indent=2)+'\n');print('network TCP listener:',len(configs),'configurations;',len(caught),'mutants;',sum(x['functions'] for x in admission),'plans admitted')
if __name__=='__main__':main()
